            for (int t = n; t > 1; t >>= 1) P++;   // log2(n)
            double* bkr = stackalloc double[32];
            double* bki = stackalloc double[32];
            bkr[P - 1] = -1.0; bki[P - 1] = 0.0;                    // B_{P-1} = exp(-πi)
            if (P >= 2) { bkr[P - 2] = 0.0; bki[P - 2] = -1.0; }    // B_{P-2} = exp(-πi/2)
