                double a = bkr[k + 1];                    // cos(angle_{k+1})
                double c = math.sqrt((1.0 + a) * 0.5);    // cos(angle_k), angle_k = angle_{k+1}/2
                bkr[k] = c;
                bki[k] = bki[k + 1] / (2.0 * c);          // -sin(angle_k), cancellation-free
            }
