            // Use workspace scratch (no per-call allocation).
            var cz = ws.cz;   // doubleN of length n/2 = M
            var sz = ws.sz;   // doubleN of length n/2 = M

            // k=0: X[0] = E[0]+O[0] and X[M] = E[0]-O[0] (both purely real).
            cz[0] = (re[0] + re[M]) * (double)0.5;
            sz[0] = (re[0] - re[M]) * (double)0.5;

            // General bins k = 1..M-1.
            // Same algebra as the recurrence irfft, but conj(W_N^k) = (twReFull[k], -twImFull[k]).
            //   E[k] = (X[k] + conj(X[M-k])) / 2
            //   O[k] = (X[k] - conj(X[M-k])) · conj(W_N^k) / 2
            //   Y[k] = E[k] + i·O[k]
            var twReFull = ws.twReFull;
            var twImFull = ws.twImFull;
            var sw1re    = ws.sw1re;
            var sw1im    = ws.sw1im;
            var cw1re    = ws.cw1re;
            var cw1im    = ws.cw1im;
            for (int k = 1; k < M; k++)
            {
                int kr = M - k;
                double xr_k  = re[k],  xi_k  = im[k];
                double xr_kr = re[kr], xi_kr = im[kr];

                // E[k] = (X[k] + conj(X[M-k])) / 2
                double E_re = (xr_k + xr_kr) * (double)0.5;
                double E_im = (xi_k - xi_kr) * (double)0.5;

                // (X[k] - conj(X[M-k])) = a + i·b
                double a = xr_k - xr_kr;
                double b = xi_k + xi_kr;

                // conj(W_N^k) = (twReFull[k], -twImFull[k]).
                // O[k] = (a + i·b) · conj(W_N^k) / 2  →  complex multiply (a+ib)·(cRe+icIm):
