                double cRe = twReFull[k];
                double cIm = -twImFull[k];   // negate imaginary part for conjugate
                double O_re = (a * cRe - b * cIm) * (double)0.5;
                double O_im = (b * cRe + a * cIm) * (double)0.5;

                // Y[k] = E[k] + i·O[k]
                cz[k] = E_re - O_im;
                sz[k] = E_im + O_re;
